/** Değerler dil bağımsız string; anahtar yapısı Türkçe sözlükten (özyinelemeli). */
type DerinSozluk<T> = {
  [K in keyof T]: T[K] extends string ? string : DerinSozluk<T[K]>;
};

export type CeviriSozlugu = DerinSozluk<typeof tr>;
